from datetime import date, datetime, timedelta
from unittest import mock

import pytest

from dispatch.case import scheduled
from dispatch.case.enums import CaseStatus


def _fake_date(today):
    class FakeDate(date):
        @classmethod
        def today(cls):
            return today

    return FakeDate


@pytest.mark.parametrize(
    "today,expected",
    [
        (date(2025, 8, 18), True),  # Monday
        (date(2025, 8, 19), False),
        (date(2025, 8, 24), False),  # Sunday
    ],
)
def test_is_reminder_day(today, expected):
    with mock.patch.object(scheduled, "date", _fake_date(today)):
        assert scheduled._is_reminder_day() is expected


@pytest.mark.parametrize("job,status", [
    (scheduled.case_close_reminder, CaseStatus.triage),
    (scheduled.case_stable_reminder, CaseStatus.stable),
])
@pytest.mark.parametrize("today,sent", [(date(2025, 8, 18), True), (date(2025, 8, 19), False)])
def test_weekly_close_reminders_only_sent_on_mondays(job, status, today, sent):
    case = mock.Mock()
    case.triage_at = case.stable_at = datetime.utcnow() - timedelta(days=10)
    # unwrap the scheduler/project decorators and call the task body directly
    task = job
    while hasattr(task, "__wrapped__"):
        task = task.__wrapped__

    with (
        mock.patch.object(scheduled, "date", _fake_date(today)),
        mock.patch.object(scheduled, "get_all_by_status", return_value=[case]),
        mock.patch.object(scheduled, "send_case_close_reminder") as send,
    ):
        task(db_session=mock.Mock(), project=mock.Mock(id=1))

    assert send.called is sent
